-- Add explicit, genre-faithful forward movement to every built-in beat (27 arcs, 262 beats).
-- Each update is protected by exact canonical previous text; custom text remains unchanged.
-- Roles, labels, UUIDs, order, and project-specific customizations are preserved.
WITH creative(template_id, beat_role, old_description, progression) AS (
VALUES
  ('A0000001-0000-0000-0000-000000000001'::uuid, 'setup', 'Introduce the world, characters, and the ordinary life that will be disrupted.', 'Begin with a volatile choice whose personal consequences make the old life unstable, not a neutral inventory of traits.'),
  ('A0000001-0000-0000-0000-000000000001'::uuid, 'inciting_incident', 'The event that disrupts the ordinary world and sets the story in motion.', 'An unmistakable, genre-specific disruption destroys one ordinary option and unleashes a new desire or danger.'),
  ('A0000001-0000-0000-0000-000000000001'::uuid, 'first_plot_point', 'The protagonist commits to the central conflict and the story tilts into Act II.', 'Let an impulsive commitment sacrifice an escape route and create a problem the opening characters could not anticipate.'),
  ('A0000001-0000-0000-0000-000000000001'::uuid, 'rising_action', 'Escalating complications, subplots, and stakes as the protagonist pursues the goal.', 'Build radically different kinds of trouble through clashing appetites, escalating decisions, and independently acting people; each alters the next objective.'),
  ('A0000001-0000-0000-0000-000000000001'::uuid, 'midpoint', 'Deliver a surprising, character-caused reversal that changes the conflict itself, not merely its difficulty.', 'Spring an earned, astonishing reversal that changes who holds power, what the goal means, or whom to trust.'),
  ('A0000001-0000-0000-0000-000000000001'::uuid, 'crisis', 'The lowest point — what looks like defeat, the dark night of the soul.', 'Make accumulated choices annihilate the strategy that has worked so far; no encore of an earlier humiliation or lesson.'),
  ('A0000001-0000-0000-0000-000000000001'::uuid, 'climax', 'Force an extraordinary, irreversible, genre-faithful act that transforms the characters'' world.', 'Stage the one decisive, unforgettable outcome in a signature character-caused action; earlier scenes cannot pre-complete it.'),
  ('A0000001-0000-0000-0000-000000000001'::uuid, 'resolution', 'Show the changed final situation, what is settled, and what meaningfully remains unresolved.', 'Show consequences in a newly altered world through action, loss, pleasure, or revelation; do not replay the climactic choice.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'ordinary_world', 'The hero''s normal life before the adventure begins.', 'Start with a vivid dependency or private appetite that the adventure will make impossible to maintain.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'call_to_adventure', 'The hero is presented with a problem, challenge, or opportunity.', 'An irresistible or terrifying summons changes an actual relationship and immediately eliminates a familiar option.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'refusal_of_call', 'The hero hesitates or refuses the adventure, fearing the unknown.', 'Let refusal trigger an unexpected loss, betrayal, temptation, or complication; mere second thoughts do not fill a beat.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'meeting_mentor', 'The hero meets a guide who gives advice, training, or confidence.', 'Give the guide an independent, flawed agenda and a consequential bargain, not an interchangeable motivational speech.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'crossing_threshold', 'The hero commits to the adventure and enters the special world.', 'Make crossing a point of no return cost a person, privilege, or belief the hero cannot simply recover.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'tests_allies_enemies', 'The hero faces trials, makes friends, and identifies antagonists.', 'Each encounter must introduce a different power, bizarre alliance, danger, or temptation that changes the objective.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'approach_inmost_cave', 'The hero nears the central ordeal, often facing a major fear.', 'Use an intimate betrayal or unnerving discovery to make the anticipated ordeal more dangerous than previously understood.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'ordeal', 'The hero''s greatest test — a life-or-death moment of transformation.', 'Break the hero''s existing strategy through an extraordinary physical or emotional event, reserving later final transformation.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'reward', 'The hero claims something of value after surviving the ordeal.', 'Make the reward alter loyalties and tempt a disastrous new choice rather than functioning as a static prize.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'road_back', 'The hero begins the return journey, often with new stakes.', 'Let apparent progress unleash a consequence or pursuit that transforms the route home.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'resurrection', 'Force a defining, extreme final test that proves what the journey has made the hero, for good or ill.', 'Reserve the final defining choice or ordeal here; it must change who the hero has become, for better or worse.'),
  ('A0000001-0000-0000-0000-000000000002'::uuid, 'return_with_elixir', 'The hero returns to the ordinary world, changed, with something to share.', 'Return to transformed relationships and a changed world where the result is enacted, not explained again.'),
  ('A0000001-0000-0000-0000-000000000003'::uuid, 'the_crime', 'Establish the crime, mystery, or question that drives the story.', 'Give the opening wrong or impossible question an intimate, irresistible human consequence that creates immediate action.'),
  ('A0000001-0000-0000-0000-000000000003'::uuid, 'investigation_begins', 'The detective/protagonist takes the case and starts gathering evidence.', 'An early investigative move should cost access, safety, trust, or freedom, establishing why the search cannot be routine.'),
  ('A0000001-0000-0000-0000-000000000003'::uuid, 'first_suspect', 'An early suspect appears strong but is misdirection.', 'Let a compelling suspect''s independent desire produce a consequential misdirection, not just a misleading statement.'),
  ('A0000001-0000-0000-0000-000000000003'::uuid, 'rising_tension', 'Stakes escalate, more clues surface, complications mount.', 'Escalate through varied dangerous encounters and changing relationships rather than another batch of interchangeable clues.'),
  ('A0000001-0000-0000-0000-000000000003'::uuid, 'key_revelation', 'A pivotal clue reshapes the investigation.', 'Use one hard-earned discovery to reverse whom the protagonist trusts or what the underlying question is.'),
  ('A0000001-0000-0000-0000-000000000003'::uuid, 'false_solution', 'The protagonist (or reader) is led to a wrong conclusion.', 'Make the seductive false answer prompt an irreversible choice whose fallout creates the next mystery state.'),
  ('A0000001-0000-0000-0000-000000000003'::uuid, 'real_clue', 'The actual culprit or truth becomes visible.', 'Reveal the crucial new evidence through human action or risk, distinct from the earlier false answer.'),
  ('A0000001-0000-0000-0000-000000000003'::uuid, 'confrontation', 'Reveal the earned truth in a dangerous, character-specific confrontation that irreversibly changes loyalties or lives.', 'Give the reserved revelation an explosive personal confrontation with one defensible solution; never solve it twice.'),
  ('A0000001-0000-0000-0000-000000000003'::uuid, 'resolution', 'The case is closed and the world has changed.', 'Force a concrete new life or relationship consequence from the truth; no evidence recap or explanatory victory lap.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'opening_image', 'Show the protagonist and world before the story changes.', 'Open on a surprising character action that vividly establishes a status quo already under strain.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'theme_stated', 'Hint at the central question or tension the protagonist must face; no moral lesson is required.', 'Let an argument, desire, or incident expose an unresolved contradiction without handing down a moral lesson.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'setup', 'Establish the cast, want, flaw, and stakes before the disruption.', 'Make the ensemble pursue incompatible wants that are poised to collide rather than merely listing their backstories.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'catalyst', 'An event makes the old status quo impossible to maintain.', 'A genre-specific rupture irrevocably changes the options available to everyone who matters.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'debate', 'The protagonist weighs the risks of responding to the new problem.', 'Put a dangerous bargain or tempting alternative on the table with consequences, not pages of indecision.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'break_into_two', 'The protagonist chooses an approach and enters a changed situation.', 'A bold choice forecloses the earlier route and launches a new arena of action.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'b_story', 'Introduce the relationship or secondary thread that carries the theme.', 'Give a secondary relationship its own independent gamble that tangles causally with the main conflict.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'fun_and_games', 'Deliver imaginative, varied events that embody the unique promise of this premise rather than repeating one type of obstacle.', 'Deliver startling and varied premise-specific set pieces; each must create a new opportunity, danger, or broken allegiance.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'midpoint', 'A false victory or defeat raises the stakes and changes the game.', 'Flip the apparent meaning of victory or failure through a spectacular, consequential change of power.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'bad_guys_close_in', 'External pressure and internal flaws tighten around the protagonist.', 'Allow previously made choices to provoke heterogeneous retaliation, betrayal, and escalating costs, not repeated obstacles.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'all_is_lost', 'The protagonist reaches a visible low point and loses a source of hope.', 'Take away something genuinely irreplaceable through the character''s own flawed action.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'dark_night_of_the_soul', 'The protagonist confronts what must change to move forward.', 'Use loss to precipitate a surprising new desire or decision, not another speech about the same truth.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'break_into_three', 'A realization combines the A and B stories into a new plan.', 'Change the strategy through a costly collision of primary and secondary relationships, without completing the reserved finale.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'finale', 'Deliver an exceptional, emotionally charged final action whose consequences cannot simply be tidied away.', 'Pay off the central conflict only here in an inventive, emotionally seismic action whose consequences endure.'),
  ('A0000001-0000-0000-0000-000000000004'::uuid, 'final_image', 'Echo the opening image to show how the world or protagonist changed.', 'Show the final transformed condition through a fresh concrete moment, never a replay of the climax.'),
  ('A0000001-0000-0000-0000-000000000005'::uuid, 'you', 'Show the character in a zone of comfort and establish what they want.', 'Make comfort vivid and compromised by one action that sets an unstable desire in motion.'),
  ('A0000001-0000-0000-0000-000000000005'::uuid, 'need', 'The character enters an unfamiliar situation to pursue a need.', 'An urgent need forces a costly exit rather than a restatement of existing dissatisfaction.'),
  ('A0000001-0000-0000-0000-000000000005'::uuid, 'go', 'The character adapts while facing escalating obstacles.', 'Introduce an unfamiliar, seductive complication that requires a genuinely new tactic or alliance.'),
  ('A0000001-0000-0000-0000-000000000005'::uuid, 'search', 'The character experiments, learns, and pays a price for progress.', 'Make experimentation produce an unexpected cost or reversal that changes the search itself.'),
  ('A0000001-0000-0000-0000-000000000005'::uuid, 'find', 'The character gets what they sought, often with an unexpected cost.', 'Obtaining the prize should reveal an astonishing new consequence, not conclude the entire arc prematurely.'),
  ('A0000001-0000-0000-0000-000000000005'::uuid, 'take', 'The character pays a consequential price for pursuing or possessing what they found.', 'Extract a dangerous, irreversible price for possessing the prize, changing the character''s relationships or power.'),
  ('A0000001-0000-0000-0000-000000000005'::uuid, 'return', 'The character returns to a familiar world carrying the consequences.', 'Return to a changed social world where old habits cannot solve the new situation.'),
  ('A0000001-0000-0000-0000-000000000005'::uuid, 'change', 'Show the character transformed through a bold, specific choice or consequence, for better, worse, or stranger.', 'Show transformation through a decisive new act—liberating, ruinous, absurd, or sublime—not a lesson restated.'),
  ('A0000001-0000-0000-0000-000000000006'::uuid, 'exposition', 'Introduce the world, characters, conflict, and conditions of the story.', 'Establish compelling people already making incompatible choices that threaten the existing order.'),
  ('A0000001-0000-0000-0000-000000000006'::uuid, 'rising_action', 'Complications build as choices intensify the central conflict.', 'Let different desires collide in increasingly surprising acts; every escalation must change stakes or alliances.'),
  ('A0000001-0000-0000-0000-000000000006'::uuid, 'climax', 'Deliver an irreversible confrontation or choice at maximum intensity, surprising in its event and inevitable in hindsight.', 'Reserve the breathtaking irreversible dramatic collision here; no preceding beat may resolve its defining event.'),
  ('A0000001-0000-0000-0000-000000000006'::uuid, 'falling_action', 'Consequences unfold and remaining conflicts move toward resolution.', 'Unleash distinct fallout, reversals of fortune, and new personal costs rather than a subdued replay of the collision.'),
  ('A0000001-0000-0000-0000-000000000006'::uuid, 'denouement', 'Show the changed final situation and what is resolved, uncertain, or unsettled.', 'Pay off the changed world through a final consequential choice or image, without tidying away the story''s darker implications.'),
  ('A0000001-0000-0000-0000-000000000007'::uuid, 'ki', 'Establish the setting, characters, and initial idea.', 'Introduce a vivid pattern or relationship whose beauty, strangeness, or tension promises further change.'),
  ('A0000001-0000-0000-0000-000000000007'::uuid, 'sho', 'Develop the situation and deepen the world without a major reversal.', 'Deepen through inventive contrast and newly consequential encounters, not a second demonstration of the same motif.'),
  ('A0000001-0000-0000-0000-000000000007'::uuid, 'ten', 'Introduce a daring new perspective or event that recasts everything established without manufacturing a villain.', 'An extraordinary juxtaposition or event overturns what the earlier pattern meant without forcing a conventional villain.'),
  ('A0000001-0000-0000-0000-000000000007'::uuid, 'ketsu', 'Connect the elements and reveal a new relationship or meaning between them, without requiring harmony.', 'Create a changed understanding expressed through a new action or relationship, not a repeated explanation of the twist.'),
  ('A0000001-0000-0000-0000-000000000008'::uuid, 'ordinary_life', 'Establish each lead''s life, unmet need, and emotional defenses before the relationship changes them.', 'Establish two combustible private lives through different risky choices that make their future collision consequential.'),
  ('A0000001-0000-0000-0000-000000000008'::uuid, 'meet_attraction', 'Bring the leads together and create a meaningful spark, friction, or pull between them.', 'Give attraction an eccentric, difficult, highly specific encounter that changes both leads'' immediate plans.'),
  ('A0000001-0000-0000-0000-000000000008'::uuid, 'resistance', 'Give the leads credible internal or external reasons not to pursue the relationship.', 'Let conflicting desires provoke new action, temptation, or sacrifice rather than iterative talks about whether to date.'),
  ('A0000001-0000-0000-0000-000000000008'::uuid, 'connection_deepens', 'Build trust, chemistry, shared experience, and vulnerability through consequential interaction.', 'Deepen desire through surprising shared gambles and collisions with others'' independent agendas, not interchangeable reassurances.'),
  ('A0000001-0000-0000-0000-000000000008'::uuid, 'midpoint_intimacy', 'Cross an emotional or physical threshold that makes the relationship harder to dismiss.', 'Make intimacy trigger an irreversible shift in loyalty, power, exposure, or future options; the relationship cannot simply reset.'),
  ('A0000001-0000-0000-0000-000000000008'::uuid, 'pressure_test', 'Apply outside stakes and personal flaws that strain the growing bond.', 'Apply a fresh, external consequence of loving this person that requires a different choice from earlier resistance.'),
  ('A0000001-0000-0000-0000-000000000008'::uuid, 'rupture', 'Break the relationship or its apparent future through a choice, revelation, fear, or betrayal.', 'Break the bond through a character-caused, genuinely new betrayal or loss, not a replay of previous doubts.'),
  ('A0000001-0000-0000-0000-000000000008'::uuid, 'realization', 'Force the central emotional truth into view and make avoidance impossible.', 'Make the changed understanding compel risky action; realizing the same problem twice is not a separate development.'),
  ('A0000001-0000-0000-0000-000000000008'::uuid, 'grand_choice', 'Demand a daring, costly, unmistakably romantic action that transforms both lives and earns the promised future.', 'Reserve a bold, costly, unmistakable romantic deed for this beat; it must create the promised relationship outcome once.'),
  ('A0000001-0000-0000-0000-000000000008'::uuid, 'hea_hfn', 'Resolve the core romantic conflict with an earned committed future together.', 'Show the earned HEA or HFN through a vivid changed-life action, not another negotiation of already agreed terms.'),
  ('A0000001-0000-0000-0000-000000000009'::uuid, 'normal_surface', 'Establish a believable domestic or psychological status quo with subtle fault lines underneath.', 'Begin with a magnetic, plausible relationship already shaped by one disturbing, consequential contradiction.'),
  ('A0000001-0000-0000-0000-000000000009'::uuid, 'destabilizing_incident', 'Introduce the event, discovery, or behavior that makes the protagonist question what is real or safe.', 'An unsettling incident changes what the protagonist can safely believe or do, not just their level of anxiety.'),
  ('A0000001-0000-0000-0000-000000000009'::uuid, 'suspicion_grows', 'Accumulate contradictions, evasions, and threatening details without resolving them too early.', 'Let specific evasions and an independently motivated person''s actions produce escalating, different dangers.'),
  ('A0000001-0000-0000-0000-000000000009'::uuid, 'first_reveal', 'Confirm that an important assumption was wrong and reframe the danger.', 'Confirm a shocking misjudgment that makes the next threat fundamentally unlike the first.'),
  ('A0000001-0000-0000-0000-000000000009'::uuid, 'isolation', 'Reduce the protagonist''s reliable support, credibility, options, or sense of control.', 'Cut off real allies, credibility, or freedom through human decisions; avoid repeating the same suspicious conversation.'),
  ('A0000001-0000-0000-0000-000000000009'::uuid, 'midpoint_truth_shift', 'Reveal a larger truth that changes who appears dangerous and what is at stake.', 'Unmask a deeply personal truth that shifts guilt, leverage, or desire and drives a new action.'),
  ('A0000001-0000-0000-0000-000000000009'::uuid, 'apparent_answer', 'Offer a convincing explanation or temporary solution that seems to settle the central suspicion.', 'Make the persuasive false answer induce a costly, irreversible mistake rather than a temporary feeling of relief.'),
  ('A0000001-0000-0000-0000-000000000009'::uuid, 'deeper_betrayal', 'Expose the hidden betrayal, manipulation, or threat beneath the apparent answer.', 'Turn apparent safety into intimate betrayal through a different character''s active agenda and unexpected choice.'),
  ('A0000001-0000-0000-0000-000000000009'::uuid, 'final_confrontation', 'Force a genuinely unnerving clash with the true source of danger and a revelation that changes the protagonist''s world.', 'Reserve the one dreadful, explosive confrontation and central revelation for this beat; its outcome cannot occur earlier.'),
  ('A0000001-0000-0000-0000-000000000009'::uuid, 'aftermath', 'Resolve the immediate threat and show the psychological or relational cost of what was uncovered.', 'Leave a changed psychological and relational reality enacted through a final fresh consequence, not exposition.'),
  ('A0000001-0000-0000-0000-000000000010'::uuid, 'ordinary_world', 'Establish the protagonist, the fantasy world, and the emotional conditions before disruption.', 'Introduce a dazzling, dangerous fantasy-world condition that makes an intimate desire difficult or forbidden.'),
  ('A0000001-0000-0000-0000-000000000010'::uuid, 'magical_disruption', 'Introduce the threat, power, mission, or revelation that overturns the status quo.', 'Let magical upheaval annihilate an existing allegiance, safety, or belief through a startling event.'),
  ('A0000001-0000-0000-0000-000000000010'::uuid, 'dangerous_attraction', 'Create a compelling romantic pull complicated by allegiance, danger, status, or mistrust.', 'Spark consuming attraction via a risky collision that alters the stakes of the fantasy conflict itself.'),
  ('A0000001-0000-0000-0000-000000000010'::uuid, 'binding_choice', 'Force a commitment that ties the protagonist to both the external conflict and romantic counterpart.', 'Bind lovers and world conflict through a costly oath, bargain, or action neither can casually undo.'),
  ('A0000001-0000-0000-0000-000000000010'::uuid, 'quest_and_bond', 'Escalate fantasy-world pressures and consequential choices while trust, desire, and mutual dependence deepen.', 'Deliver distinct wondrous perils and divided loyalties; each encounter transforms magic, trust, or the mission.'),
  ('A0000001-0000-0000-0000-000000000010'::uuid, 'midpoint_revelation', 'Reveal a truth about the world, power, danger, or relationship that changes the trajectory.', 'Reveal an astonishing magical or personal truth that changes the lovers'' choices and the world''s rules.'),
  ('A0000001-0000-0000-0000-000000000010'::uuid, 'divided_loyalties', 'Make romantic desire and external duty meaningfully conflict.', 'Demand an active betrayal, dangerous gamble, or impossible loyalty choice with lasting damage.'),
  ('A0000001-0000-0000-0000-000000000010'::uuid, 'catastrophic_break', 'Shatter the current plan or relationship and expose the cost of choosing wrongly.', 'Destroy an essential bond, power, or plan through a spectacular consequence rather than repeated romantic doubt.'),
  ('A0000001-0000-0000-0000-000000000010'::uuid, 'united_choice', 'Have the leads choose what they will stand for together despite the cost.', 'Earn a surprising mutual commitment through an action that changes the possible final confrontation.'),
  ('A0000001-0000-0000-0000-000000000010'::uuid, 'final_battle_and_choice', 'Deliver an astonishing fantasy consequence decided by a defining, costly romantic choice; no literal battle is required.', 'Reserve a breathtaking fantasy outcome inseparable from the decisive romantic act; resolve neither ahead of this slot.'),
  ('A0000001-0000-0000-0000-000000000010'::uuid, 'new_order_together', 'Establish the changed world and the earned state of the relationship.', 'Stage the changed world and relationship in a new consequential act, avoiding another version of the final vow.'),
  ('A0000001-0000-0000-0000-000000000011'::uuid, 'threat_appears', 'Introduce a concrete danger with consequences the protagonist cannot ignore.', 'Start with an alarming, particular threat that wrecks a meaningful relationship or status quo in action.'),
  ('A0000001-0000-0000-0000-000000000011'::uuid, 'clock_starts', 'Create a meaningful deadline and force the protagonist into action.', 'Make the deadline change what is possible; force an immediate sacrifice or terrible practical commitment.'),
  ('A0000001-0000-0000-0000-000000000011'::uuid, 'first_pursuit', 'Escalate active danger through pursuit, evasion, discovery, or consequential failed attempts, whichever fits the story.', 'Use a distinctive risky encounter to eliminate one plan and introduce an entirely different vulnerability.'),
  ('A0000001-0000-0000-0000-000000000011'::uuid, 'narrowing_options', 'Close off easy solutions and make delay increasingly costly.', 'Close off resources through clever adversarial choices and unexpected personal consequences, not recycled pursuits.'),
  ('A0000001-0000-0000-0000-000000000011'::uuid, 'midpoint_reversal', 'Change the protagonist''s understanding of the threat, target, or enemy.', 'Reframe the true target or danger with a revelation that transforms the escape strategy.'),
  ('A0000001-0000-0000-0000-000000000011'::uuid, 'major_loss', 'Inflict a serious failure or loss that makes the deadline feel nearly impossible.', 'Inflict an irreversible loss that changes who can act or what survival now means.'),
  ('A0000001-0000-0000-0000-000000000011'::uuid, 'final_lead', 'Reveal an earned opening, hard choice, or opportunity that makes one last attempt possible.', 'Make a risky, earned opening arrive through someone''s morally complicated decision, not a free clue.'),
  ('A0000001-0000-0000-0000-000000000011'::uuid, 'race_to_deadline', 'Compress time and escalate obstacles as the protagonist commits everything to the final attempt.', 'Pressure time with varied catastrophes and escalating compromises; every move must irreversibly change the endgame.'),
  ('A0000001-0000-0000-0000-000000000011'::uuid, 'showdown', 'At the deadline, force an inventive, decisive sacrifice or gamble that produces the promised suspense payoff.', 'Spend the one decisive deadline collision in this slot through a surprising earned action, not an earlier rescue.'),
  ('A0000001-0000-0000-0000-000000000011'::uuid, 'aftermath', 'Show the immediate consequences and the new state after the threat is resolved.', 'Show consequences the protagonist must live with after the clock stops, not a second climactic chase.'),
  ('A0000001-0000-0000-0000-000000000012'::uuid, 'baseline_world', 'Establish the system, environment, technology, and ordinary operating assumptions.', 'Establish a specific technological or ecological normal through a human choice whose complacency will matter.'),
  ('A0000001-0000-0000-0000-000000000012'::uuid, 'impossible_problem', 'Introduce the anomaly, disaster, discovery, or survival problem that breaks those assumptions.', 'Make an impossible phenomenon shatter a foundational rule and threaten a relationship or survival option.'),
  ('A0000001-0000-0000-0000-000000000012'::uuid, 'first_hypothesis', 'Commit to an initial explanation or solution based on the best available evidence.', 'Let the first hypothesis demand a dangerous commitment that alters later access, alliances, or resources.'),
  ('A0000001-0000-0000-0000-000000000012'::uuid, 'failed_solution', 'Demonstrate that the first approach is insufficient and make the problem more dangerous or complex.', 'Disprove the solution with a strange, escalating result; the failed attempt must leave new damage.'),
  ('A0000001-0000-0000-0000-000000000012'::uuid, 'deeper_discovery', 'Reveal a staggering new truth or rule that transforms the problem and demands a deeply personal response.', 'Reveal a reality-changing truth that recasts both survival and the characters'' own identities or motives.'),
  ('A0000001-0000-0000-0000-000000000012'::uuid, 'resource_collapse', 'Remove critical time, energy, safety, personnel, or technological capacity.', 'Destroy a distinct essential resource through someone else''s self-interested choice, not another abstract systems alert.'),
  ('A0000001-0000-0000-0000-000000000012'::uuid, 'breakthrough', 'Achieve the conceptual or technical insight that makes a real solution possible.', 'Earn a startling new possibility through observed consequences of earlier failures, transforming the plan.'),
  ('A0000001-0000-0000-0000-000000000012'::uuid, 'sacrifice_choice', 'Force a costly decision about what must be risked or surrendered for the solution to work.', 'Make the necessary sacrifice personal, specific, and irreversible rather than a generic noble speech.'),
  ('A0000001-0000-0000-0000-000000000012'::uuid, 'final_solution', 'Execute the decisive solution under maximum pressure.', 'Reserve the astonishing decisive act or experiment and actual survival outcome for this beat.'),
  ('A0000001-0000-0000-0000-000000000012'::uuid, 'changed_world', 'Resolve survival and show how the discovery permanently changes the characters or world.', 'Show a transformed world and changed bonds through new events, not a technical after-action report.'),
  ('A0000001-0000-0000-0000-000000000013'::uuid, 'controlled_normal', 'Establish the rules, rewards, punishments, and normalized compromises of the oppressive system.', 'Reveal the system''s seductive rewards and violence through the protagonist''s own compromised action.'),
  ('A0000001-0000-0000-0000-000000000013'::uuid, 'crack_in_system', 'Expose a contradiction, injustice, or forbidden truth that the protagonist cannot unsee.', 'An outrageous contradiction or intimate betrayal makes the old participation impossible to sustain.'),
  ('A0000001-0000-0000-0000-000000000013'::uuid, 'awakening', 'Turn private doubt into a clearer understanding of the system and the protagonist''s place in it.', 'Turn awareness into a personally dangerous change of allegiance; no repeat of the first injustice.'),
  ('A0000001-0000-0000-0000-000000000013'::uuid, 'first_defiance', 'Make an irreversible act of resistance that creates real consequences.', 'Force a public or secret irreversible act that draws a new kind of retaliation.'),
  ('A0000001-0000-0000-0000-000000000013'::uuid, 'resistance_builds', 'Expand allies, tactics, and stakes while the regime becomes more aware of the threat.', 'Let independently motivated allies seize, exploit, or corrupt the resistance and transform its aims.'),
  ('A0000001-0000-0000-0000-000000000013'::uuid, 'regime_retaliates', 'Demonstrate the system''s power through punishment, repression, or targeted loss.', 'Strike at a specific relationship or resource in a brutal, inventive response that alters the struggle.'),
  ('A0000001-0000-0000-0000-000000000013'::uuid, 'betrayal_or_loss', 'Break trust or remove a key source of hope, forcing a reassessment of the rebellion.', 'Shatter a crucial alliance through a believable betrayal with costs nobody can undo.'),
  ('A0000001-0000-0000-0000-000000000013'::uuid, 'uprising_choice', 'Commit to the decisive action despite the personal and collective cost.', 'Commit to a new, dangerous mode of resistance and surrender an option the protagonist valued.'),
  ('A0000001-0000-0000-0000-000000000013'::uuid, 'confrontation', 'Make the defining clash an irreversible rupture that exposes what gaining power really costs, not just a formal change of control.', 'Deliver one unforgettable clash or overthrow that transforms the meaning of power, not just its custodian.'),
  ('A0000001-0000-0000-0000-000000000013'::uuid, 'new_order_cost', 'Show what changed, what did not, and what the victory or failure ultimately cost.', 'Show what the new order does to people through a distinctive consequence, not a policy briefing.'),
  ('A0000001-0000-0000-0000-000000000014'::uuid, 'dangerous_encounter', 'Introduce an attraction carrying credible emotional, social, moral, or physical risk.', 'Begin with disturbing magnetism and a risky encounter that creates a dangerous new dependency or choice.'),
  ('A0000001-0000-0000-0000-000000000014'::uuid, 'boundary_drawn', 'Expose a dangerous imbalance or forbidden limit that intensifies the attraction and provokes consequential choices; this is not a recurring discussion of relationship rules.', 'Make an actual transgressive act cross an unstable limit and change leverage; do not stage a relationship-rules seminar.'),
  ('A0000001-0000-0000-0000-000000000014'::uuid, 'entanglement', 'Make desire, secrecy, dependence, and compromising choices collide until a new situation becomes inescapable.', 'Force desire into a scandalous, reckless entanglement that closes off an exit or betrays someone important.'),
  ('A0000001-0000-0000-0000-000000000014'::uuid, 'power_shift', 'Change who holds leverage or what each character believes about the other.', 'Reverse who holds power through a shocking intimate gamble, not a second argument about control.'),
  ('A0000001-0000-0000-0000-000000000014'::uuid, 'vulnerability_revealed', 'Expose a truth or wound that complicates the apparent power dynamic.', 'Expose a wound or secret through consequential intimacy or treachery that transforms attraction into a different danger.'),
  ('A0000001-0000-0000-0000-000000000014'::uuid, 'moral_pressure', 'Force the relationship against a meaningful ethical, emotional, or external limit.', 'Force an inventive, morally unsettling action whose price cannot be paid by reassurance or apology.'),
  ('A0000001-0000-0000-0000-000000000014'::uuid, 'betrayal_or_rupture', 'Break trust or make continuation of the relationship appear unacceptable or impossible.', 'Rupture the bond through a devastating new betrayal or irreversible deed, not earlier anxiety repeated louder.'),
  ('A0000001-0000-0000-0000-000000000014'::uuid, 'reckoning', 'Force an emotionally explosive encounter with the relationship''s real price; it may intensify devotion, ruin it, corrupt it, or change it, not automatically redeem anyone.', 'Confront a radically changed situation where love, obsession, and power demand an explosive act, not therapy dialogue.'),
  ('A0000001-0000-0000-0000-000000000014'::uuid, 'chosen_terms', 'Deliver a bold, costly, defining choice about the bond through decisive action rather than a list of healthy boundaries.', 'Reserve the one defining, costly, potentially ferocious relationship decision for this beat; do not perform it earlier.'),
  ('A0000001-0000-0000-0000-000000000014'::uuid, 'earned_resolution', 'Resolve the central romance through a memorable, earned choice with lasting consequences; the future may remain obsessive, precarious, dangerous, or morally unsettling.', 'Deliver a passionate, haunting, or precarious future through fresh consequences of the chosen act, never tidy rehabilitation by default.'),
  ('A0000001-0000-0000-0000-000000000015'::uuid, 'threatened_home', 'Establish the world and the danger that makes remaining unchanged impossible.', 'Show an irreplaceable home or bond jeopardized by a vivid, strange personal mistake.'),
  ('A0000001-0000-0000-0000-000000000015'::uuid, 'call_or_mission', 'Define the quest, objective, or burden that must be undertaken.', 'Let a dangerous call or impossible bargain make the quest''s first objective urgent and consequential.'),
  ('A0000001-0000-0000-0000-000000000015'::uuid, 'fellowship_forms', 'Assemble the companions, alliances, or obligations needed for the journey.', 'Give companions outrageous independent desires and one binding choice that creates future conflict.'),
  ('A0000001-0000-0000-0000-000000000015'::uuid, 'first_threshold', 'Leave safety behind and enter the true arena of the quest.', 'Cross into a wonder or terror that destroys the group''s ability to return unchanged.'),
  ('A0000001-0000-0000-0000-000000000015'::uuid, 'trials_and_world', 'Escalate obstacles while revealing the scale, cultures, powers, and costs of the conflict.', 'Make every new culture, creature, or trial force a distinct irreversible change in alliance, power, or mission.'),
  ('A0000001-0000-0000-0000-000000000015'::uuid, 'midpoint_revelation', 'Reveal a truth about the enemy, artifact, prophecy, mission, or protagonist that changes the quest.', 'Unveil a mind-altering truth that transforms the meaning of the object, prophecy, or enemy.'),
  ('A0000001-0000-0000-0000-000000000015'::uuid, 'catastrophic_setback', 'Break the plan, fellowship, or hope through a major defeat or loss.', 'Shatter the fellowship or goal through an extraordinary defeat, not another similar ambush.'),
  ('A0000001-0000-0000-0000-000000000015'::uuid, 'regroup_and_sacrifice', 'Recommit through a costly choice informed by what the journey has taught.', 'Earn a new route through a costly and surprising act of love, betrayal, or sacrifice.'),
  ('A0000001-0000-0000-0000-000000000015'::uuid, 'final_objective', 'Deliver a breathtaking and causally earned event that transforms the world''s future at a profound personal price.', 'Reserve the immense decisive outcome for one breathtaking confrontation or choice unique to this world.'),
  ('A0000001-0000-0000-0000-000000000015'::uuid, 'return_or_new_age', 'Show the transformed world, surviving relationships, and consequences of the quest.', 'Show a permanently transformed civilization through lived human consequences, not a summary of kingdoms.'),
  ('A0000001-0000-0000-0000-000000000016'::uuid, 'hook', 'Establish the protagonist, central lack, and starting conditions in direct contrast with the eventual ending.', 'Establish a sharp contradiction through a defining choice that gives the ending meaningful contrast.'),
  ('A0000001-0000-0000-0000-000000000016'::uuid, 'plot_turn_one', 'Introduce the event that commits the protagonist to the central story problem.', 'Trigger a startling irreversible event that commits the protagonist to an unfamiliar kind of trouble.'),
  ('A0000001-0000-0000-0000-000000000016'::uuid, 'pinch_point_one', 'Apply direct pressure from a person, circumstance, or opposing force and demonstrate the cost of failure.', 'Have danger expose a previously hidden relationship flaw through a costly, distinctive collision.'),
  ('A0000001-0000-0000-0000-000000000016'::uuid, 'midpoint', 'Shift the protagonist from reaction toward active pursuit through a major realization or reversal.', 'Turn reaction into active pursuit after a revelation that changes what success means.'),
  ('A0000001-0000-0000-0000-000000000016'::uuid, 'pinch_point_two', 'Deliver the strongest pressure or loss before the endgame and strip away an important support.', 'Strip away a different support or allegiance through the opposing force''s independent gamble.'),
  ('A0000001-0000-0000-0000-000000000016'::uuid, 'plot_turn_two', 'Reveal or earn the final information, capacity, or decision needed to face the ending.', 'Earn a surprising resource, alliance, or truth that creates a new and dangerous final option.'),
  ('A0000001-0000-0000-0000-000000000016'::uuid, 'resolution', 'Pay off the core contrast through a decisive, genre-faithful transformation, never a routine wrap-up.', 'Pay off the contrast in one genre-specific, shattering action whose resulting reality cannot be reset.'),
  ('A0000001-0000-0000-0000-000000000017'::uuid, 'normal_with_crack', 'Establish ordinary life while planting a specific detail that feels wrong before its meaning is known.', 'Let an uncanny, precise detail drive a character into a bad choice before anyone knows why.'),
  ('A0000001-0000-0000-0000-000000000017'::uuid, 'first_intrusion', 'Let the threat cross into the protagonist''s world in a way that can no longer be fully ignored.', 'Make the impossible intrude through a disturbing event with a tangible, irreversible personal effect.'),
  ('A0000001-0000-0000-0000-000000000017'::uuid, 'denial_or_misread', 'Allow a plausible explanation or wrong interpretation to delay full understanding.', 'Let an attractive false explanation provoke a disastrous decision instead of merely postponing belief.'),
  ('A0000001-0000-0000-0000-000000000017'::uuid, 'confirmation', 'Prove that the threat is real and more dangerous than initially believed.', 'Prove the horror with a grotesque manifestation that changes the danger''s nature.'),
  ('A0000001-0000-0000-0000-000000000017'::uuid, 'isolation', 'Cut off safety, help, escape, credibility, or familiar rules.', 'Sever safety or trust in a new and terrifying way; not another repetition of an ominous clue.'),
  ('A0000001-0000-0000-0000-000000000017'::uuid, 'rules_discovered', 'Reveal or complicate the threat''s behavior and the cost of confronting it, without requiring a solvable rule.', 'Reveal a nightmarish pattern that compels a different form of survival, without turning horror into rules paperwork.'),
  ('A0000001-0000-0000-0000-000000000017'::uuid, 'false_safety', 'Offer a temporary escape or solution that fails to end the threat.', 'Offer tempting relief through an act that secretly worsens the threat and destroys a valued refuge.'),
  ('A0000001-0000-0000-0000-000000000017'::uuid, 'full_manifestation', 'Bring the horror into an unmistakably nightmarish form that destroys safety or meaning, not a generic threatening encounter.', 'Unleash an unforgettable horror that transforms what the protagonists believe can happen to bodies or minds.'),
  ('A0000001-0000-0000-0000-000000000017'::uuid, 'survival_confrontation', 'Force the protagonist into the decisive encounter with the threat.', 'Reserve the defining confrontation with the threat, and its irreversible result, for this beat alone.'),
  ('A0000001-0000-0000-0000-000000000017'::uuid, 'final_image', 'Leave a haunting, specifically horrific aftershock whether anyone survives, escapes, or becomes part of the horror.', 'Leave a specifically horrifying changed reality through a new final image, not explanation or an extra showdown.'),
  ('A0000001-0000-0000-0000-000000000018'::uuid, 'season_setup', 'Establish the athletic stakes, team or competitive environment, and each lead''s current priorities.', 'Seed competitive obsession and dangerous desire through a vivid decision with a personal price; not a rules briefing.'),
  ('A0000001-0000-0000-0000-000000000018'::uuid, 'meet_or_rivalry', 'Create the relationship spark through competition, collision, recruitment, or a shared sports context.', 'Let the sporting collision spark risky chemistry and a rivalry with independent, surprising motives.'),
  ('A0000001-0000-0000-0000-000000000018'::uuid, 'forced_proximity', 'Give the leads a credible reason to spend meaningful time together despite resistance.', 'Force contact through a precarious shared gamble or obligation that changes both leads'' options.'),
  ('A0000001-0000-0000-0000-000000000018'::uuid, 'chemistry_builds', 'Deepen attraction and trust while training, competition, or team pressures escalate.', 'Make athletic pressure turn intimacy into reckless, consequential action; avoid a second training-and-boundaries scene.'),
  ('A0000001-0000-0000-0000-000000000018'::uuid, 'first_commitment', 'Cross a relationship threshold that makes the connection real and consequential.', 'Cross the relationship threshold through a costly act that changes career, loyalty, or public stakes.'),
  ('A0000001-0000-0000-0000-000000000018'::uuid, 'public_private_pressure', 'Bring career, team, reputation, family, or media pressures against the relationship.', 'Unleash a fresh humiliation, sabotage, temptation, or public reversal that creates a NEW conflict beyond old publicity fights.'),
  ('A0000001-0000-0000-0000-000000000018'::uuid, 'athletic_setback', 'Create a meaningful competitive loss, injury, failure, or career threat that changes priorities.', 'Make the sporting loss or injury actually change the competition path; establish any later qualification in credible causality.'),
  ('A0000001-0000-0000-0000-000000000018'::uuid, 'relationship_rupture', 'Break the couple''s apparent future at the moment both sport and relationship stakes peak.', 'Rupture the bond through a new betrayal or major choice under changed sporting stakes, not another caretaker disagreement.'),
  ('A0000001-0000-0000-0000-000000000018'::uuid, 'game_day_choice', 'Make the defining athletic moment and romantic decision collide in one emotionally charged, unforgettable payoff.', 'Reserve a surprising, memorable sporting result and the defining love choice for one intertwined payoff.'),
  ('A0000001-0000-0000-0000-000000000018'::uuid, 'hea_hfn', 'Deliver the earned relationship future and show how it fits with the characters'' athletic lives.', 'Enact an earned romantic future through an exciting changed life, not a negotiated safety checklist or second victory.'),
  ('A0000001-0000-0000-0000-000000000019'::uuid, 'danger_hook', 'Introduce the threat that forces the leads into the same problem.', 'Open with intimate jeopardy that destroys one lead''s previous freedom and makes the other personally consequential.'),
  ('A0000001-0000-0000-0000-000000000019'::uuid, 'forced_alliance', 'Make cooperation necessary even though trust is incomplete.', 'Make an uneasy alliance arise from a dangerous irreversible compromise rather than convenient cooperation.'),
  ('A0000001-0000-0000-0000-000000000019'::uuid, 'distrust', 'Expose reasons the leads cannot yet fully rely on one another.', 'An independent secret or gamble should cause a specific breach of trust and a newly dangerous choice.'),
  ('A0000001-0000-0000-0000-000000000019'::uuid, 'intimacy_under_pressure', 'Deepen attraction and vulnerability while danger keeps increasing.', 'Let desire trigger an audacious risk that changes the threat''s reach, not just soften a chase.'),
  ('A0000001-0000-0000-0000-000000000019'::uuid, 'threat_escalates', 'Make the antagonist or danger more immediate, capable, and personal.', 'Introduce a genuinely different attack, betrayal, or peril that demands a new joint tactic.'),
  ('A0000001-0000-0000-0000-000000000019'::uuid, 'midpoint_reveal', 'Reveal a truth that changes both the danger and the relationship.', 'Reveal a personal truth that changes the enemy''s plan and the lovers'' power over each other.'),
  ('A0000001-0000-0000-0000-000000000019'::uuid, 'betrayal_or_misread', 'Break trust or make one lead appear complicit with the threat.', 'Break trust through a consequential misreading or betrayal caused by the established danger, not another argument.'),
  ('A0000001-0000-0000-0000-000000000019'::uuid, 'trust_choice', 'Make an active, risky decision to trust based on earned knowledge rather than convenience.', 'Force a risky protective choice that forfeits a safe option and makes the final showdown possible.'),
  ('A0000001-0000-0000-0000-000000000019'::uuid, 'joint_showdown', 'Resolve the danger through surprising coordinated action driven by an emotionally costly romantic decision, not just exposure or outside rescue.', 'Reserve the one inventive, breathtaking resolution of peril intertwined with the decisive romantic act for this beat.'),
  ('A0000001-0000-0000-0000-000000000019'::uuid, 'safety_and_commitment', 'Resolve the threat and establish the earned romantic future.', 'Show the resulting relationship and safety through an action neither lead could have taken before the climax.'),
  ('A0000001-0000-0000-0000-000000000020'::uuid, 'discovery', 'Uncover the object, document, secret, or anomaly that opens the larger mystery.', 'Introduce a bizarre or seductive discovery with immediate consequences for a living relationship, not just an object inventory.'),
  ('A0000001-0000-0000-0000-000000000020'::uuid, 'pursuit_begins', 'Make possession of the discovery dangerous and force the protagonist to act.', 'Make an independently motivated person''s action turn knowledge into dangerous pursuit and irreversibly close an option.'),
  ('A0000001-0000-0000-0000-000000000020'::uuid, 'first_clue', 'Resolve the first layer while pointing toward a larger hidden system.', 'Let the first clue reverse a specific belief and unleash a new human conflict.'),
  ('A0000001-0000-0000-0000-000000000020'::uuid, 'conspiracy_expands', 'Reveal that the opposition is broader, older, or more powerful than expected.', 'Expand the conspiracy through a startling betrayal or new force that changes who has power.'),
  ('A0000001-0000-0000-0000-000000000020'::uuid, 'ally_or_betrayal', 'Complicate the pursuit by changing who can be trusted.', 'Have an ally pursue a selfish, plausible agenda and provoke an unforeseen loss or new possibility.'),
  ('A0000001-0000-0000-0000-000000000020'::uuid, 'hidden_history_reveal', 'Expose the deeper origin or meaning of the artifact, conspiracy, or secret.', 'Reveal a world-altering history that recasts present loyalties rather than furnishing an evidence packet.'),
  ('A0000001-0000-0000-0000-000000000020'::uuid, 'apparent_defeat', 'Put the antagonist in control and remove the protagonist''s obvious path forward.', 'Destroy a critical belief, refuge, or ally through a shocking, causal move by the opposition.'),
  ('A0000001-0000-0000-0000-000000000020'::uuid, 'final_decoding', 'Complete the insight that reveals what must happen next and why.', 'Earn an astonishing new interpretation that changes what the protagonists must do next, not a second clue reading.'),
  ('A0000001-0000-0000-0000-000000000020'::uuid, 'race_to_prevent', 'Escalate toward the irreversible consequence the conspiracy is trying to cause.', 'Make the approaching catastrophe provoke varied irreversible choices, not an endless sequence of logistical checkpoints.'),
  ('A0000001-0000-0000-0000-000000000020'::uuid, 'confrontation_and_truth', 'Turn the astonishing but earned truth into irreversible upheaval through a high-stakes confrontation, not revelation alone.', 'Deliver the one grand, shocking truth and its decisive human consequences in a singular confrontation.'),
  ('A0000001-0000-0000-0000-000000000020'::uuid, 'aftermath', 'Resolve the immediate conspiracy and show what the revealed truth changes.', 'Show how reality and relationships actually changed through a fresh final consequence, not another reveal.'),
  ('A0000001-0000-0000-0000-000000000021'::uuid, 'weak_start', 'Establish the protagonist''s limitations, status, and the hierarchy they cannot yet overcome.', 'Give low status a strange, humiliating, personal cost that drives a consequential act.'),
  ('A0000001-0000-0000-0000-000000000021'::uuid, 'system_discovered', 'Reveal the rules, power system, progression path, or game-like structure that makes advancement possible.', 'Reveal the system through a thrilling experiment or encounter that changes the protagonist''s choices.'),
  ('A0000001-0000-0000-0000-000000000021'::uuid, 'first_gain', 'Earn the first meaningful improvement and commit to progression.', 'Make the first gain produce a startling new obligation or enemy, not merely a number increase.'),
  ('A0000001-0000-0000-0000-000000000021'::uuid, 'training_and_trials', 'Build competence through increasingly costly practice, quests, tests, or fights.', 'Vary training with perilous bargains, rival gambles, bizarre quests, and distinct changes of power.'),
  ('A0000001-0000-0000-0000-000000000021'::uuid, 'first_boss', 'Measure progress against an opponent or challenge that exposes remaining weaknesses.', 'Use a spectacular test to reveal a different flaw than the protagonist has already faced.'),
  ('A0000001-0000-0000-0000-000000000021'::uuid, 'new_tier', 'Achieve a breakthrough that changes the protagonist''s options and status.', 'Let the new tier unlock a shocking freedom, temptation, or threat that transforms the central objective.'),
  ('A0000001-0000-0000-0000-000000000021'::uuid, 'stronger_rival', 'Introduce an opponent, faction, or challenge that makes the new level insufficient.', 'Give the rival an original appetite and a dangerous choice that redefines the meaning of strength.'),
  ('A0000001-0000-0000-0000-000000000021'::uuid, 'major_defeat', 'Inflict a loss that exposes a fundamental weakness in the current path.', 'Break the current progression strategy with a costly defeat and irreversible loss.'),
  ('A0000001-0000-0000-0000-000000000021'::uuid, 'breakthrough', 'Earn a new understanding, technique, alliance, or evolution through the consequences of defeat.', 'Earn a radically different approach through changed loyalties or an inventive discovery, not repeat training.'),
  ('A0000001-0000-0000-0000-000000000021'::uuid, 'tier_climax', 'Pay off hard-won powers and relationships in a spectacular, inventive trial with lasting consequences beyond a level increase.', 'Reserve one dazzling culmination of new powers and relationships; its outcome must be irrevocable.'),
  ('A0000001-0000-0000-0000-000000000021'::uuid, 'next_horizon', 'Resolve the current progression arc while revealing the larger level still ahead.', 'Reveal the next horizon as a transformed world and new desire, not another copy of the prior boss.'),
  ('A0000001-0000-0000-0000-000000000022'::uuid, 'life_before', 'Establish the social world, relationships, duties, and historical conditions before open rupture.', 'Establish period-specific desire, loyalty, and frailty through a choice that history will make costly.'),
  ('A0000001-0000-0000-0000-000000000022'::uuid, 'war_arrives', 'Bring the historical conflict directly into the protagonist''s life.', 'Let war destroy one intimate arrangement through an unforgettable, historically plausible event.'),
  ('A0000001-0000-0000-0000-000000000022'::uuid, 'adaptation', 'Force new roles, routines, allegiances, or survival strategies.', 'Force a desperate new role or dangerous compromise that changes relationships rather than merely routines.'),
  ('A0000001-0000-0000-0000-000000000022'::uuid, 'first_loss', 'Make the cost of the conflict personal and irreversible.', 'Inflict a singular personal loss whose consequences drive the next conflict, not recurring anonymous casualties.'),
  ('A0000001-0000-0000-0000-000000000022'::uuid, 'deepening_conflict', 'Escalate scarcity, danger, displacement, duty, or divided loyalties.', 'Escalate through varied scarcity, passion, absurd luck, treachery, and unpredictable human decisions.'),
  ('A0000001-0000-0000-0000-000000000022'::uuid, 'impossible_choice', 'Force a decision in which every available option carries serious moral or personal cost.', 'Demand an impossible moral or survival act that forfeits something specific and beloved.'),
  ('A0000001-0000-0000-0000-000000000022'::uuid, 'major_loss_or_betrayal', 'Destroy a major source of safety, trust, or hope.', 'Destroy a different refuge or loyalty through a shocking betrayal that alters the route ahead.'),
  ('A0000001-0000-0000-0000-000000000022'::uuid, 'final_endurance', 'Commit to the final course of action under the harshest conditions.', 'Make endurance a reckless, costly human decision that sets up but does not resolve the final event.'),
  ('A0000001-0000-0000-0000-000000000022'::uuid, 'decisive_event', 'Deliver a historically grounded, extraordinary decisive event whose survival, betrayal, or loss changes everything.', 'Reserve a historically grounded, extraordinarily consequential victory, escape, death, or betrayal for this beat.'),
  ('A0000001-0000-0000-0000-000000000022'::uuid, 'aftermath_and_memory', 'Show survival, grief, change, and what the historical experience leaves behind.', 'Show the transformed survivor and community through lived action, not a history lecture or another sacrifice.'),
  ('A0000001-0000-0000-0000-000000000023'::uuid, 'sheltered_identity', 'Establish the protagonist''s inherited identity, assumptions, and limited understanding of the world.', 'Open with a magnetic young person making a compromised choice inside the inherited world.'),
  ('A0000001-0000-0000-0000-000000000023'::uuid, 'first_disruption', 'Introduce an experience that makes the old identity insufficient.', 'An exhilarating or catastrophic experience should permanently change what belonging is possible.'),
  ('A0000001-0000-0000-0000-000000000023'::uuid, 'experimentation', 'Let the protagonist test new roles, freedoms, relationships, or beliefs.', 'Let experimentation lead to bizarre friendships, intoxicating freedom, and a costly new consequence.'),
  ('A0000001-0000-0000-0000-000000000023'::uuid, 'belonging_and_conflict', 'Offer meaningful belonging while exposing the compromises it demands.', 'Make a seductive group or relationship demand a real betrayal, gamble, or sacrifice.'),
  ('A0000001-0000-0000-0000-000000000023'::uuid, 'first_consequence', 'Make a choice produce an irreversible emotional, social, or practical cost.', 'Force the first irreversible consequence of an original mistake, not another embarrassment.'),
  ('A0000001-0000-0000-0000-000000000023'::uuid, 'disillusionment', 'Break an important idealization of a person, institution, relationship, or self-image.', 'Destroy a treasured ideal through a person''s self-interested action, changing what the protagonist believes.'),
  ('A0000001-0000-0000-0000-000000000023'::uuid, 'self_recognition', 'Bring the protagonist to a clearer understanding of who they are and what they value.', 'Earn self-recognition through a startling choice that creates a new risk, not a reflective monologue.'),
  ('A0000001-0000-0000-0000-000000000023'::uuid, 'adult_choice', 'Make a consequential decision based on the emerging self rather than inherited expectations.', 'Make an audacious adult act foreclose the old identity and transform a relationship.'),
  ('A0000001-0000-0000-0000-000000000023'::uuid, 'leaving_or_returning', 'Show the immediate consequence of the adult choice in relation to the old world.', 'Leave or return to a changed family or community where old permissions no longer apply.'),
  ('A0000001-0000-0000-0000-000000000023'::uuid, 'integrated_identity', 'Reveal the emerging self through a startling, costly choice, whether admirable, damaged, or unsettling.', 'Show the new identity in an extraordinary, consequential action; the character need not be morally improved.'),
  ('A0000001-0000-0000-0000-000000000024'::uuid, 'injury', 'Inflict the wrong, loss, humiliation, or betrayal that creates the desire for revenge.', 'Establish a particular, devastating injury that binds the wrong to a living relationship.'),
  ('A0000001-0000-0000-0000-000000000024'::uuid, 'vow', 'Turn pain into a concrete commitment to retaliate.', 'Convert pain into an audacious irreversible commitment with an unexpected first price.'),
  ('A0000001-0000-0000-0000-000000000024'::uuid, 'preparation', 'Acquire knowledge, access, allies, skills, or leverage needed to act.', 'Build capacity through uneasy alliances and treacherous bargains that already change the avenger.'),
  ('A0000001-0000-0000-0000-000000000024'::uuid, 'first_retribution', 'Deliver an early success that proves revenge is possible and raises the stakes.', 'Give the first retaliation a thrilling, shocking result that creates an unintended new enemy or debt.'),
  ('A0000001-0000-0000-0000-000000000024'::uuid, 'cost_revealed', 'Show collateral damage or personal corruption caused by the pursuit.', 'Let collateral harm produce an independent betrayal or twisted new appetite, not another guilty thought.'),
  ('A0000001-0000-0000-0000-000000000024'::uuid, 'counterstrike', 'Let the target or system retaliate effectively and put the avenger in danger.', 'Have the target retaliate with a brilliant, intimate countermove that changes the campaign.'),
  ('A0000001-0000-0000-0000-000000000024'::uuid, 'moral_crossroads', 'Force recognition of what revenge is demanding and whether the original goal still justifies it.', 'Force a costly action with morally dangerous options, not another speech about whether revenge is right.'),
  ('A0000001-0000-0000-0000-000000000024'::uuid, 'final_hunt', 'Commit to the last pursuit with no illusion about its cost.', 'Make the final pursuit transform alliances and expose a new devastating vulnerability.'),
  ('A0000001-0000-0000-0000-000000000024'::uuid, 'reckoning', 'Force a fierce, unforgettable final confrontation; mercy, ruin, violence, or reversal must carry irrevocable costs.', 'Reserve a ferocious, surprising confrontation whose result can never be played twice.'),
  ('A0000001-0000-0000-0000-000000000024'::uuid, 'consequence', 'Resolve what revenge achieved, destroyed, or failed to repair.', 'Show the new world revenge created through a fresh consequence, even if victory feels monstrous.'),
  ('A0000001-0000-0000-0000-000000000025'::uuid, 'target', 'Establish the prize, obstacle, and why taking it matters.', 'Make the prize dangerously personal or outrageous and show why a particular character would risk everything.'),
  ('A0000001-0000-0000-0000-000000000025'::uuid, 'motive', 'Create the pressure or opportunity that makes the heist worth attempting.', 'Give the crew''s motive a scandalous complication that alters whom they trust.'),
  ('A0000001-0000-0000-0000-000000000025'::uuid, 'crew_assembled', 'Recruit the specialized people and define the tensions inside the team.', 'Assemble volatile specialists whose independent appetites create a new problem before the job begins.'),
  ('A0000001-0000-0000-0000-000000000025'::uuid, 'plan_and_prep', 'Build the operation, gather tools and intelligence, and expose likely failure points.', 'Let preparation involve a brilliant gamble or betrayal that permanently changes the plan.'),
  ('A0000001-0000-0000-0000-000000000025'::uuid, 'first_complication', 'Introduce a change that invalidates part of the plan before or during execution.', 'Destroy one planned advantage through a surprising character action; do not merely list new security obstacles.'),
  ('A0000001-0000-0000-0000-000000000025'::uuid, 'execution_begins', 'Cross the point of no return and put the plan into motion.', 'Cross the point of no return with a daring, irreversible move that triggers unforeseen opposition.'),
  ('A0000001-0000-0000-0000-000000000025'::uuid, 'plan_breaks', 'Destroy the expected path to success and force live improvisation.', 'Collapse the original method in a spectacular, personally consequential way.'),
  ('A0000001-0000-0000-0000-000000000025'::uuid, 'betrayal_or_twist', 'Reveal hidden motives, double-crosses, or a truth about the target that changes the job.', 'Let a double-cross or new truth change who wants the prize and why.'),
  ('A0000001-0000-0000-0000-000000000025'::uuid, 'improvisation', 'Use the crew''s earned skills and relationships to create a new route through the failure.', 'Create an inventive route from established skills and enemies'' desires, not a second version of the old plan.'),
  ('A0000001-0000-0000-0000-000000000025'::uuid, 'escape_or_capture', 'Pay off the heist through a daring, earned final gambit that transforms who gets the prize and whom the crew can trust.', 'Reserve a breathtaking, hard-earned decisive gambit whose result changes possession and loyalty once.'),
  ('A0000001-0000-0000-0000-000000000025'::uuid, 'division_and_aftermath', 'Settle the prize, loyalties, consequences, and what remains of the crew.', 'Pay off personal consequences through a fresh scene that remakes the crew, rather than an inventory of shares.'),
  ('A0000001-0000-0000-0000-000000000026'::uuid, 'broken_state', 'Establish the protagonist''s damaged pattern, moral failure, or self-defeating way of living.', 'Open on a vivid, damaging choice whose cost makes the character''s old pattern unmistakable.'),
  ('A0000001-0000-0000-0000-000000000026'::uuid, 'chance_to_change', 'Introduce the person, event, responsibility, or consequence that makes another path possible.', 'Let a strange person or event offer a seductive alternative that changes what is at stake.'),
  ('A0000001-0000-0000-0000-000000000026'::uuid, 'refusal_or_old_pattern', 'Show the protagonist retreating into the familiar behavior that created the problem.', 'Make refusal cause a distinct, irreversible new injury, not another demonstration of the same flaw.'),
  ('A0000001-0000-0000-0000-000000000026'::uuid, 'first_good_choice', 'Make a meaningful but incomplete choice toward change.', 'Show a tentative change through an expensive, surprising action that complicates relationships.'),
  ('A0000001-0000-0000-0000-000000000026'::uuid, 'progress', 'Build evidence of change through repeated costly choices rather than declarations.', 'Build progress across radically different temptations and choices, not a repetitive series of apologies.'),
  ('A0000001-0000-0000-0000-000000000026'::uuid, 'relapse', 'Return the protagonist to the old pattern at serious cost.', 'Make relapse transform the problem and harm someone new in a way the character cannot erase.'),
  ('A0000001-0000-0000-0000-000000000026'::uuid, 'truth_faced', 'Force full recognition of the harm, lie, or fear beneath the old identity.', 'Force recognition through a new person''s consequential action, not a repeat of the earlier confession.'),
  ('A0000001-0000-0000-0000-000000000026'::uuid, 'sacrifice', 'Give up something genuinely valued in order to act according to the new truth.', 'Give up a singular source of pleasure, power, or attachment through an irreversible gamble.'),
  ('A0000001-0000-0000-0000-000000000026'::uuid, 'redemptive_act', 'Demand an extraordinary, costly deed that proves genuine change under maximum temptation; confession alone is insufficient.', 'Reserve the extraordinary defining deed that proves or destroys change under maximum temptation.'),
  ('A0000001-0000-0000-0000-000000000026'::uuid, 'changed_life', 'Resolve with the consequences of the redemptive choice and a demonstrably different way of living.', 'Show a life demonstrably transformed through new action, without a sentimental second climax.'),
  ('A0000001-0000-0000-0000-000000000027'::uuid, 'founding_choice', 'Establish the consequential decision, relationship, wound, or ambition that shapes the family system.', 'Begin with an extravagant ambition, love, or betrayal whose effect can be inherited.'),
  ('A0000001-0000-0000-0000-000000000027'::uuid, 'first_inheritance', 'Show how the founding generation''s choices become conditions imposed on the next.', 'Make one generation''s compromise become a sharply different dilemma for another through real events.'),
  ('A0000001-0000-0000-0000-000000000027'::uuid, 'family_expands', 'Develop alliances, marriages, rivalries, resources, and competing visions across the family.', 'Build new alliances, appetites, and feuds whose independent choices disrupt the family story.'),
  ('A0000001-0000-0000-0000-000000000027'::uuid, 'buried_conflict', 'Deepen a resentment, inherited pressure, unresolved wrong, or recurring choice carried across time; a buried secret is optional.', 'Have an inherited pressure cause a surprising action, not just another retelling of the same secret.'),
  ('A0000001-0000-0000-0000-000000000027'::uuid, 'generational_turn', 'Shift power or perspective to a new generation that interprets the inheritance differently.', 'Let a new generation commit a shocking reversal that redefines what inheritance means.'),
  ('A0000001-0000-0000-0000-000000000027'::uuid, 'fracture', 'Break the family system through a death, betrayal, succession fight, revelation, or separation.', 'Shatter a previously important bond through a scandalous, irreversible rupture.'),
  ('A0000001-0000-0000-0000-000000000027'::uuid, 'inherited_truth_revealed', 'Reveal or reinterpret the inherited pattern through decisions, memory, or discovery; no hidden document is required.', 'Reveal or reinterpret the legacy through a consequential choice, not a repeated document discovery.'),
  ('A0000001-0000-0000-0000-000000000027'::uuid, 'reckoning_across_generations', 'Force living generations to confront the inherited pattern and one another.', 'Make living generations take different, incompatible actions that transform their shared conflict.'),
  ('A0000001-0000-0000-0000-000000000027'::uuid, 'reconciliation_or_repeat', 'Show whether the family transforms the pattern or consciously repeats it.', 'Force one distinct act of reunion, estrangement, or repetition whose outcome changes the family structure.'),
  ('A0000001-0000-0000-0000-000000000027'::uuid, 'legacy', 'Show an unforgettable inheritance or rupture that transforms how the reader understands every generation''s choices.', 'Leave an unforgettable inheritance or catastrophe lived in a new generation''s choices, not a recap.')
)
UPDATE public.story_arc_templates AS t
SET beats = (
  SELECT jsonb_agg(
    CASE WHEN c.beat_role IS NOT NULL
      THEN jsonb_set(b.beat, '{description}',
        to_jsonb(c.old_description || ' Creative progression: ' || c.progression), false)
      ELSE b.beat END ORDER BY b.position)
  FROM jsonb_array_elements(t.beats) WITH ORDINALITY AS b(beat, position)
  LEFT JOIN creative AS c
    ON c.template_id = t.id
   AND c.beat_role = b.beat->>'role'
   AND c.old_description = b.beat->>'description'
), updated_at = now()
WHERE EXISTS (
  SELECT 1
  FROM jsonb_array_elements(t.beats) AS beat
  JOIN creative AS c
    ON c.template_id = t.id
   AND c.beat_role = beat->>'role'
   AND c.old_description = beat->>'description'
);

-- Propagate only to already-selected beats whose exact text is still the
-- prior built-in default. Do not replace any user-edited or older wording.
UPDATE public.story_arc_beats AS b
SET details = e.beat->>'description', updated_at = now()
FROM public.story_arcs AS a
JOIN public.story_arc_templates AS t ON t.id = a.template_id
CROSS JOIN LATERAL jsonb_array_elements(t.beats) AS e(beat)
WHERE b.story_arc_id = a.id
  AND b.role = e.beat->>'role'
  AND e.beat->>'description' LIKE '% Creative progression: %'
  AND b.details = split_part(e.beat->>'description', ' Creative progression: ', 1);
